"""Generated bytes only: fixtures make no claims about real capture coverage."""
import hashlib
from pathlib import Path
import struct
import sys
import tempfile
import unittest
sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'services/analysis/src'))
from cpag_core.parsers.packet_envelope import CaptureError, Limits, inspect_capture


def pcap(frames, endian='<', nano=False, link=1):
    magic = (b'\x4d\x3c\xb2\xa1' if nano else b'\xd4\xc3\xb2\xa1') if endian == '<' else (b'\xa1\xb2\x3c\x4d' if nano else b'\xa1\xb2\xc3\xd4')
    return magic + struct.pack(endian + 'HHiiII', 2, 4, 0, 0, 65535, link) + b''.join(struct.pack(endian + 'IIII', t, 1, len(b), len(b)) + b for t, b in frames)


def block(kind, body, endian='<'):
    length = len(body) + 12
    return struct.pack(endian + 'II', kind, length) + body + struct.pack(endian + 'I', length)


def pcapng(frames, endian='<'):
    return block(0x0a0d0d0a, struct.pack(endian + 'IHHq', 0x1a2b3c4d, 1, 0, -1), endian) + block(1, struct.pack(endian + 'HHI', 1, 0, 65535), endian) + b''.join(block(6, struct.pack(endian + 'IIIII', 0, 0, t, len(b), len(b)) + b + b'\0' * (-len(b) % 4), endian) for t, b in frames)


class EnvelopeTests(unittest.TestCase):
    def run_bytes(self, data, **kwargs):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'synthetic.capture'
            path.write_bytes(data)
            return inspect_capture(path, synthetic=True, **kwargs)

    def test_pcap_variants_and_references(self):
        for endian in ('<', '>'):
            for nano in (False, True):
                data = pcap([(2, b'abc')], endian, nano)
                result = self.run_bytes(data)
                frame = result['frames'][0]
                self.assertEqual(frame['raw_timestamp'], 2 * (10**9 if nano else 10**6) + 1)
                self.assertEqual(data[frame['byte_offset']:frame['byte_offset'] + frame['captured_length']], b'abc')
                self.assertEqual(frame['file_sha256'], hashlib.sha256(data).hexdigest())
                self.assertEqual(result['events'], [])

    def test_pcapng_both_orders(self):
        for endian in ('<', '>'):
            result = self.run_bytes(pcapng([(123, b'abc')], endian))
            self.assertEqual(result['frames'][0]['raw_timestamp'], 123)
            self.assertEqual(result['frames'][0]['ticks_per_second'], 1000000)

    def test_tcp_duplicate_segments_reordered_and_unanswered_retained_only(self):
        def packet(seq, payload, port=44818):
            tcp = struct.pack('!HHIIBBHHH', 1234, port, seq, 0, 80, 24, 4096, 0, 0) + payload
            ip = struct.pack('!BBHHHBBH4s4s', 69, 0, 20 + len(tcp), 1, 0, 64, 6, 0, bytes([192,0,2,1]), bytes([192,0,2,2]))
            return b'\0'*12 + b'\x08\x00' + ip + tcp
        # Same direction only: duplicate sequence/data, later segment before first,
        # another payload with no reply, and a non-target destination port.
        frames = [(5, packet(100, b'abc')), (6, packet(100, b'abc')),
                  (7, packet(106, b'ghi')), (8, packet(103, b'def')),
                  (9, packet(109, b'unanswered')), (10, packet(500, b'http', 80))]
        for data in (pcap(frames), pcapng(frames)):
            result = self.run_bytes(data)
            self.assertEqual(len(result['frames']), 6)
            self.assertEqual(result['frames'][0]['frame_sha256'], result['frames'][1]['frame_sha256'])
            self.assertEqual([f['transport']['sequence_number'] for f in result['frames']], [100,100,106,103,109,500])
            self.assertEqual([f['transport']['destination_port'] for f in result['frames']], [44818]*5 + [80])
            self.assertEqual(result['events'], [])
            for indexed, (_, raw) in zip(result['frames'], frames):
                self.assertEqual(data[indexed['byte_offset']:indexed['byte_offset'] + indexed['captured_length']], raw)
                self.assertEqual(indexed['transport']['reason'], 'application_semantics_unsupported')
                self.assertNotIn('correlation_id', indexed)
                self.assertNotIn('response_status', indexed)

    def test_literal_hex_golden_not_generated_by_helpers(self):
        # Hand-written LE PCAP: timestamp 2s+1us; a 54-byte Ethernet/IPv4/TCP
        # frame 192.0.2.1:1234 -> 192.0.2.2:44818, seq=100, no payload.
        data = bytes.fromhex(
            'd4c3b2a1020004000000000000000000ffff000001000000'
            '02000000010000003600000036000000'
            '0000000000000000000000000800'
            '450000280001000040060000c0000201c0000202'
            '04d2af1200000064000000005018100000000000')
        frame = self.run_bytes(data)['frames'][0]
        self.assertEqual(frame['byte_offset'], 40)
        self.assertEqual(frame['captured_length'], 54)
        self.assertEqual(frame['raw_timestamp'], 2000001)
        self.assertEqual(frame['transport']['destination_port'], 44818)
        self.assertEqual(frame['transport']['sequence_number'], 100)
        self.assertEqual(frame['transport']['tcp_payload_length'], 0)
        self.assertEqual(data[40:], bytes.fromhex('0000000000000000000000000800450000280001000040060000c0000201c000020204d2af1200000064000000005018100000000000'))

    def test_multiple_interfaces_and_timestamp_options_rejected(self):
        shb = pcapng([])[:28]
        idb = block(1, struct.pack('<HHI', 1, 0, 65535))
        with self.assertRaisesRegex(CaptureError, 'multiple_interfaces_unsupported'):
            self.run_bytes(shb + idb + idb)
        # if_tsresol code 9, one-byte exponent 9, padding then end option.
        for exponent in (6, 9, 0x8a):
            option = struct.pack('<HHB', 9, 1, exponent) + b'\0'*3 + b'\0'*4
            with self.assertRaisesRegex(CaptureError, 'interface_options_unsupported'):
                self.run_bytes(shb + block(1, struct.pack('<HHI', 1, 0, 65535) + option))

    def test_truncation_and_corruption_fail_without_partial_result(self):
        for data in (pcap([(1, b'abc')]), pcapng([(1, b'abc')])):
            for cut in range(1, len(data)):
                # Complete header/block prefixes are valid empty captures; exclude them.
                if cut in (24, 28, 48):
                    continue
                with self.assertRaises(CaptureError):
                    self.run_bytes(data[:cut])
        bad = bytearray(pcapng([])); bad[-1] = 1
        with self.assertRaises(CaptureError):
            self.run_bytes(bad)

    def test_capture_truncation_metadata(self):
        data = bytearray(pcap([(1, b'abc')]))
        struct.pack_into('<I', data, 36, 10)
        frame = self.run_bytes(data)['frames'][0]
        self.assertEqual(frame['original_length'], 10)
        self.assertIn('capture_truncated', frame['quality'])

    def test_unsupported_links_options_sections(self):
        for data in (pcap([], link=101), pcapng([]) + pcapng([]), pcapng([]) + block(99, b''),
                     block(0x0a0d0d0a, struct.pack('<IHHq', 0x1a2b3c4d, 1, 0, -1)) + block(1, struct.pack('<HHI', 1, 0, 65535) + b'\0'*4)):
            with self.assertRaises(CaptureError): self.run_bytes(data)

    def test_transport_headers_only(self):
        tcp = struct.pack('!HHIIBBHHH', 1234, 44818, 100, 0, 80, 24, 4096, 0, 0) + b'opaque'
        ip = struct.pack('!BBHHHBBH4s4s', 69, 0, 20 + len(tcp), 1, 0, 64, 6, 0, bytes([192,0,2,1]), bytes([192,0,2,2]))
        ethernet = b'\0' * 12 + b'\x08\x00'
        transport = self.run_bytes(pcap([(1, ethernet + ip + tcp)]))['frames'][0]['transport']
        self.assertEqual(transport['source_ip'], '192.0.2.1')
        self.assertEqual(transport['destination_port'], 44818)
        self.assertEqual(transport['tcp_payload_length'], 6)
        self.assertEqual(transport['reason'], 'application_semantics_unsupported')
        fragmented = bytearray(ip); fragmented[6] = 32
        transport = self.run_bytes(pcap([(1, ethernet + fragmented + tcp)]))['frames'][0]['transport']
        self.assertEqual(transport['reason'], 'ip_fragment_reassembly_unsupported')
        self.assertNotIn('destination_port', transport)

    def test_limits_and_gate(self):
        data = pcap([(1, b'abc'), (2, b'def')])
        for limits in (Limits(max_bytes=5), Limits(max_frames=1), Limits(max_frame_bytes=2)):
            with self.assertRaises(CaptureError): self.run_bytes(data, limits=limits)
        with self.assertRaises(CaptureError): inspect_capture('/does/not/exist')
        with self.assertRaises(ValueError): Limits(max_frames=True)

if __name__ == '__main__': unittest.main()
